import sys
sys.setrecursionlimit(10000)

class Solution:
    def countPathSums(self, root: Optional[TreeNode], target: int) -> int:
        def from_here(node, need):
            if not node:
                return 0
            rest = need - node.val
            return (rest == 0) + from_here(node.left, rest) + from_here(node.right, rest)

        def every(node):
            if not node:
                return 0
            return from_here(node, target) + every(node.left) + every(node.right)

        return every(root)

