function countPathSums(root: TreeNode | null, target: number): number {
  const seen = new Map<number, number>([[0, 1]]);
  const dfs = (node: TreeNode | null, running: number): number => {
    if (!node) return 0;
    running += node.val;
    let count = seen.get(running - target) ?? 0;
    seen.set(running, (seen.get(running) ?? 0) + 1);
    count += dfs(node.left, running) + dfs(node.right, running);
    seen.set(running, seen.get(running)! - 1); // leave this branch
    return count;
  };
  return dfs(root, 0);
}

